// === Tab: main.js ===
var word = "LEADSHOW";
var wordSize = 100;
var speedToTriggerDynState = 3;
var splitCount = 3;
var minHue = 115;
var maxHue = 150;
var currentHue = minHue;
var font;
var particles = [];

function preload() {
  font = loadFont("https://openprocessing.org/sketch/916837/files/AvenirNextLTPro-Demi.otf");
}

function setup() { 
  createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 255);
	reset();
}

function draw() {
  background(0, 100);

  for (let i = particles.length - 1; i > -1; i--) {
		particles[i].move();
    stroke(particles[i].color);
    strokeWeight(particles[i].size);
    point(particles[i].pos.x, particles[i].pos.y);

    if (particles[i].pos.y > height || particles[i].pos.x < 0 || particles[i].pos.x > width) {
      particles.splice(i, 1);
    }
  }
}

function mouseClicked() {
	reset();
}

function reset() {
	background(0);

	particles = [];

  let spawnPoints = font.textToPoints(word, width / 2, height / 2, wordSize, {sampleFactor: 0.6});
	spawnPoints.sort((pnt1, pnt2) => (pnt1.x > pnt2.x) ? 1 : -1);

	let firstPoint = spawnPoints[0];
	let lastPoint = spawnPoints[spawnPoints.length - 1];
	let wordHalfWidth = (lastPoint.x - firstPoint.x) / 2.0;

  for (let i = 0; i < spawnPoints.length; i++) {
		let x = spawnPoints[i].x - wordHalfWidth;
		let y = spawnPoints[i].y;
		let newParticle = new Particle(x, y, 1);
		newParticle.setTarget(x, y);
    particles.push(newParticle);
  }
}

// === Tab: particle.js ===
function Particle(x, y, pSize) {
	this.size = pSize;
  this.color = color(255);
	this.gravityAmount = random(0.15, 0.25);
  this.pos = new p5.Vector(x, y);
  this.vel = new p5.Vector(0, 0);
  this.acc = new p5.Vector(0, 0);
	this.target = null;

	this.avoidMouse = function() {
    let mouseDist = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let mouseThresh = 100;

    if (mouseDist < mouseThresh) {
      let pushForce = new p5.Vector(this.pos.x, this.pos.y);
      pushForce.sub(new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
      pushForce.normalize();
      pushForce.mult((mouseThresh - mouseDist) * 0.0025);
      this.acc.add(pushForce);
    }
	}

	this.setTarget = function(x, y) {
		this.target = new p5.Vector(x, y);	
	}

	this.seekTarget = function() {
		let targetDist = dist(this.pos.x, this.pos.y, this.target.x, this.target.y);
		let speedMultiplier = 1;
		let distThresh = 50;

		if (targetDist < distThresh) {
			speedMultiplier = targetDist / distThresh;
		}

		if (targetDist > 1) {
			let steer = new p5.Vector(this.target.x, this.target.y);
			steer.sub(this.pos);
			steer.normalize();
			steer.mult(0.05 * speedMultiplier);
			this.acc.add(steer);
		}
	}

	this.shiftHue = function() {
		currentHue += 0.1;
		if (currentHue > maxHue) {
			currentHue = minHue;
		}
	}

	this.makeDynamic = function() {
		this.target = null;
		this.size = random(0.25, 3);
		this.color = color(currentHue, 255, 255);
		this.shiftHue();

		for (let i = 0; i < splitCount; i++) {
			var newParticle = new Particle(this.pos.x, this.pos.y, random(0.25, 3));

			newParticle.vel.set(this.vel.x, this.vel.y);
			newParticle.vel.mult(random(0.9, 1.1));
			newParticle.vel.rotate(radians(random(-25, 25)));

			if (i < splitCount - 1) {
				newParticle.color = color(currentHue, 255, 255);
				this.shiftHue();
			}

			particles.push(newParticle);
		}
	}

  this.move = function() {
		this.vel.mult(0.99);

    if (this.target != null) {
			this.seekTarget();

      if (this.vel.mag() > speedToTriggerDynState) {
				this.makeDynamic();
      }
    } else {
      this.acc.add(new p5.Vector(0, this.gravityAmount));
    }

		this.avoidMouse();

    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }
}

